    if (batch_idx >= batch_size) return;

    const float* x = input + (size_t)batch_idx * norm_size;
    float* y = output + (size_t)batch_idx * norm_size;

    const float m = mean[batch_idx];
    const float istd = inv_std[batch_idx];

