    const float4* b_vec = reinterpret_cast<const float4*>(beta);

    int vec_idx = idx_base / 4 + threadIdx.x;
    int num_vec = norm_size / 4;

    if (vec_idx < num_vec) {
        float4 val = x_vec[vec_idx];
        float4 g = g_vec[vec_idx];
        float4 b = b_vec[vec_idx];

